  _globals['_IMAGESERVICE'].methods_by_name['GetImage']._serialized_options = b'\222A\205\002\n\006Images\022\022Get an image by ID\032\243\001Retrieves a specific image within the given scope. The scope_id determines visibility: tenant scope sees tenant images; project scope sees project + tenant images.J/\n\003200\022(\n\002OK\022\"\n \032\036.firebird.api.v1.ImageResponseb\020\n\016\n\nBearerAuth\022\000\202\323\344\223\002\'\022%/compute/images/{scope_id}/{image_id}'
